# Let me properly test my hypothesis
rules = [('gg', 'u'), ('g', 'ggd')]

# Test on all inputs
test_results = []
for inp in inputs:
    result = inp
    for pattern, replacement in rules:
        result = result.replace(pattern, replacement)
    test_results.append(result)

print("Testing rules:", rules)
print("Input -> Output")
for i, (inp, outp, res) in enumerate(zip(inputs, outputs, test_results)):
    print(f"{inp} -> {res} (expected {outp})")

# Check for over-applications
