over_apps = []
for i, (inp, expected_out) in enumerate(zip(inputs, outputs)):
    result = inp
    for pattern, replacement in rules:
        result = result.replace(pattern, replacement)

    if result != expected_out:
        over_apps.append((i, inp, result))

if over_apps:
    print("Over-applications found:")
    for idx, inp, out in over_apps:
        print(f"  Index {idx}: {inp} -> {out} (expected {outputs[idx]})")
